<template><section class="workbench" data-cpf-page="unified-operations-dashboard"><header class="header"><div><h1>CPF 통합 운영 Dashboard</h1><p>Online·Gateway·Batch·Recovery·Approval 상태를 동일 Freshness 기준으로 요약하고 원인 화면으로 Deep Link합니다.</p></div><button :disabled="loading" @click="load">새로고침</button></header><p v-if="error" class="state error">{{ error }}</p><article class="panel"><div class="header"><div><h2>Central Runtime Inventory</h2><p>Dashboard는 별도 Server 목록을 가지지 않고 공통 Runtime Registry를 사용합니다.</p></div></div><RuntimeInventorySelector v-model="centralRuntimeId" /></article><div class="cards"><article class="card"><span>CPF Platform</span><strong>{{ text(platform,'platformVersion','version') }}</strong><small>{{ text(platform,'compatibleRange','compatible_range') }}</small></article><RouterLink class="card" :to="{name:'runtimeControl'}"><span>Runtime Control</span><strong>{{ text(health,'status','state','health') }}</strong><small>{{ text(status,'updatedAt','updated_at') }}</small></RouterLink><RouterLink class="card" :to="{name:'incidents'}"><span>Unknown Result</span><strong>{{ unknown.length }}</strong><small>{{ risky(unknown) }} 조치 필요</small></RouterLink><RouterLink class="card" :to="{name:'incidents'}"><span>Broker DLQ</span><strong>{{ dlq.length }}</strong><small>{{ risky(dlq) }} 미해결</small></RouterLink><RouterLink class="card" :to="{name:'batch-executions'}"><span>Batch Execution</span><strong>{{ batchItems.length }}</strong><small>{{ risky(batchItems) }} 실패/불명</small></RouterLink><RouterLink class="card" :to="{name:'reliability'}"><span>Outbox</span><strong>{{ outbox.length }}</strong><small>{{ risky(outbox) }} 지연/재시도</small></RouterLink><RouterLink class="card" :to="{name:'transactionGroups'}"><span>Causal Trace</span><strong>SEARCH</strong><small>Online→Batch 통합 추적</small></RouterLink></div><article class="panel"><div class="header"><h2>운영 우선순위</h2><span class="muted">Freshness {{ fetchedAt||'-' }}</span></div><div class="table-wrap"><table><thead><tr><th>우선순위</th><th>영역</th><th>상태</th><th>식별자</th><th>Transaction</th></tr></thead><tbody><tr v-for="(row,index) in priorityRows" :key="index"><td>{{ index+1 }}</td><td>{{ row.area }}</td><td>{{ text(row.data,'status','state') }}</td><td>{{ text(row.data,'unknownId','messageId','executionId','id') }}</td><td>{{ text(row.data,'transactionId','transaction_id') }}</td></tr><tr v-if="!priorityRows.length"><td colspan="5">현재 수집된 고위험 항목이 없습니다.</td></tr></tbody></table></div></article></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { RouterLink } from 'vue-router';import RuntimeInventorySelector from '../../components/RuntimeInventorySelector.vue';import { findDlq,findOutbox,findRuntimeHealth,findRuntimeStatus,findUnknownResults,type JsonMap } from './api';import { admQuery } from '../../shared/cpfApi';import { admPlatformVersion } from '../../generated/cpf-api';import { errorMessage,read,text } from './support';const centralRuntimeId=ref(''),health=ref<JsonMap>({}),status=ref<JsonMap>({}),unknown=ref<JsonMap[]>([]),dlq=ref<JsonMap[]>([]),outbox=ref<JsonMap[]>([]),batchItems=ref<JsonMap[]>([]),platform=ref<JsonMap>({}),loading=ref(false),error=ref(''),fetchedAt=ref('');function risky(rows:JsonMap[]){return rows.filter(r=>/FAIL|ERROR|UNKNOWN|PENDING|RETRY|DLQ|STOPPED/i.test(String(read(r,'status','state')??''))).length}const priorityRows=computed(()=>[{area:'Unknown',rows:unknown.value},{area:'DLQ',rows:dlq.value},{area:'Batch',rows:batchItems.value},{area:'Outbox',rows:outbox.value}].flatMap(x=>x.rows.filter(r=>/FAIL|ERROR|UNKNOWN|PENDING|RETRY|DLQ/i.test(String(read(r,'status','state')??''))).map(data=>({area:x.area,data}))).slice(0,20));async function load(){loading.value=true;error.value='';try{const r=await Promise.allSettled([findRuntimeHealth(),findRuntimeStatus(),findUnknownResults(undefined,undefined,100),findDlq(undefined,undefined,undefined,100),findOutbox(undefined,undefined,undefined,100),admQuery<{items?:JsonMap[]}>("/adm/api/batch/executions/page",{page:0,size:100}),admPlatformVersion()]);if(r[0].status==='fulfilled')health.value=r[0].value;if(r[1].status==='fulfilled')status.value=r[1].value;if(r[2].status==='fulfilled')unknown.value=r[2].value;if(r[3].status==='fulfilled')dlq.value=r[3].value;if(r[4].status==='fulfilled')outbox.value=r[4].value;if(r[5].status==='fulfilled')batchItems.value=r[5].value.items??[];if(r[6].status==='fulfilled')platform.value=r[6].value;const failures=r.filter(x=>x.status==='rejected');if(failures.length)error.value=`일부 Owner 조회 실패 ${failures.length}/7: ${failures.map(x=>x.status==='rejected'?errorMessage(x.reason):'').join(' | ')}`;fetchedAt.value=new Date().toISOString()}finally{loading.value=false}}onMounted(load);</script><style scoped>
.workbench{display:grid;gap:1rem}.header,.actions,.tabs,.pager{display:flex;gap:.65rem;align-items:center;justify-content:space-between;flex-wrap:wrap}.header h1,.header h2{margin:0}.header p{margin:.35rem 0 0;color:#52606d}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:.7rem;align-items:end}.filters label,.dialog label{display:grid;gap:.3rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:.75rem}.card,.panel{border:1px solid #d7dde5;border-radius:.6rem;padding:1rem;background:#fff}.card strong{font-size:1.35rem;display:block}.table-wrap{overflow:auto;border:1px solid #d7dde5;border-radius:.5rem}table{border-collapse:collapse;width:100%;min-width:900px}th,td{padding:.65rem;border-bottom:1px solid #e4e8ed;text-align:left;vertical-align:top}tbody tr{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#f3f6f9}.state{padding:.75rem;border-radius:.4rem;background:#eef3f7}.state.error{background:#fff0f0;color:#a51d1d}.state.warning{background:#fff8dc;color:#715600}.state.success{background:#edf9f0;color:#126b35}.danger{background:#9d1c1c;color:white}.primary{background:#1f5f99;color:white}.detail{white-space:pre-wrap;overflow:auto;max-height:480px;background:#111827;color:#e5e7eb;padding:1rem;border-radius:.5rem}.dialog-backdrop{position:fixed;inset:0;background:#0008;display:grid;place-items:center;z-index:1000}.dialog{width:min(620px,calc(100vw - 2rem));max-height:90vh;overflow:auto;background:#fff;border-radius:.65rem;padding:1.2rem;display:grid;gap:1rem}.dialog textarea{min-height:100px}.confirm{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.muted{color:#68737d}.badge{display:inline-block;padding:.15rem .45rem;border-radius:999px;background:#e9eef5}.links{display:flex;gap:.6rem;flex-wrap:wrap}@media(max-width:720px){.header{display:grid}.actions{justify-content:flex-start}}
</style>